plates/items/falafel-plate.jpg'),('falafel-3a-zawe2ak','Mixed Pickles (1 kg)','/assets/templates/items/falafel-pickles.jpg'),('falafel-3a-zawe2ak','Pepsi','/assets/templates/items/falafel-pepsi.jpg'),('falafel-3a-zawe2ak','Ayran','/assets/templates/items/falafel-ayran.jpg'),('falafel-3a-zawe2ak','Small Water','/assets/templates/items/falafel-water.jpg'),('falafel-3a-zawe2ak','Natural Juice','/assets/templates/items/falafel-juice.jpg'))
update menu_templates t set data=jsonb_set(t.data,'{categories}',(
 select jsonb_agg(jsonb_set(c,'{items}',(select jsonb_agg(case when mm.url is not null then i||jsonb_build_object('image_url',mm.url) else i end order by o)
   from jsonb_array_elements(c->'items') with ordinality x(i,o) left join m mm on mm.code=t.code and mm.name_en=i->>'name_en')) order by co)
 from jsonb_array_elements(t.data->'categories') with ordinality y(c,co))), updated_at=now()
where t.code in ('woodyz','al-basha','falafel-3a-zawe2ak');
update menu_templates set data=jsonb_set(jsonb_set(data,'{categories,0,items,7,desc_en}','"Chicken, mozzarella, barbeque"'),'{categories,0,items,7,desc_ar}','"دجاج، موزاريلا، باربيكيو"') where code='woodyz';
update menu_templates set data=jsonb_set(jsonb_set(data,'{categories,0,items,9,desc_en}','"Alfredo sauce, chicken, mozzarella, fresh mushroom, parmesan, basil"'),'{categories,0,items,9,desc_ar}','"صلصة الألفريدو، دجاج، موزاريلا، فطر طازج، بارميزان، حبق"') where code='woodyz';
